        public decimal GetAutoSequence(string groupId)
        {
            try
            {
                return base.Query(t => t.CompanyGroupId == groupId).Select(r => r.Sequence).Max() + 1;
            }
            catch (Exception)
            {
                return 1.00m;
            }
        }

        private string PK => GetAutoNumber(nameof(MaterialMaster), PKGeneratorEnum.Auto, null, DateTime.Now);

        public void InsertGraph(MaterialMaster entity
            , IEnumerable<MaterialMasterAlternativeUOM> materialMasterAlternativeUOM
            , IEnumerable<MaterialAttributeViewModel> materialMasterAttribute
            , IEnumerable<MaterialAttributeValue> attributeValueList
            , IEnumerable<MaterialMasterCharacteristics> materialMasterCharacteristics
            , IEnumerable<CharacteristicsValue> characteristicsValue
            , IEnumerable<MaterialMasterProcessRouting> materialMasterProcessRouting
            , IEnumerable<MaterialMasterProcessSet> masterProcessSetList
            , IEnumerable<MaterialMasterBusinessProcess> businessProcesses
            , IEnumerable<MaterialMasterRevenueBudget> revenuList)
        {
            var flag = false;
            try
            {
                var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
                entity.Code = GetCode();
                CheckUnique(entity, identity.CompanyGroupId);
                _unitOfWork.BeginTransaction();
                flag = true;
                entity.Id = PK;
                entity.CompanyGroupId = identity.CompanyGroupId;
                entity.Image = entity.Image == null ? null : entity.Id + entity.Image;

                #region Business process and revenue budget

                foreach (var item in businessProcesses)
                {
                    if (item.Flag)
                        BusinessProcessInsertGraph(entity, item);
                }
                if (revenuList != null)
                {
                    foreach (var item in revenuList)
                    {
                        RevenueBudgetInsertGraph(entity, item);
                    }
                }

                #endregion Business process and revenue budget

                InsertGraph(entity);
                _materialMasterAlternativeUOM.Insert(materialMasterAlternativeUOM, entity.Id);
                //MaterialMasterProcessRouting
                ProsessRouting(entity.Id, materialMasterProcessRouting);
                // attribute with value
                if (materialMasterAttribute != null && materialMasterAttribute.Count() > 0)
                {
                    InsertGraphAttribute(entity, materialMasterAttribute);
                    _attributeValueService.InsertGraphFromMaterial(attributeValueList, materialMasterAttribute, entity.CompanyGroupId, entity.Id);
                }

                if (entity.WithSKU && (materialMasterCharacteristics != null && materialMasterCharacteristics.Count() > 0))
                {
                    InsertGraphCharacteristics(entity, materialMasterCharacteristics);
                    _characteristicsValueService.InsertGraphFromMaterial(characteristicsValue, entity.CompanyGroupId, entity.Id);
                }
                else if (entity.WithSKU && (materialMasterCharacteristics != null && materialMasterCharacteristics.Count() > 0))
                    throw new CustomException("Please define material characteristics.");
                //Process
                _masterProcessSetListService.InsertGraph(entity.Id, masterProcessSetList);

                _unitOfWork.SaveChanges();
                flag = false;
                _unitOfWork.Commit();
            }
            catch (CustomException)
            {
                throw;
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Material.ToString()));
            }
            finally
            {
                if (flag)
                    _unitOfWork.Rollback();
            }
        }

        public bool CheckMaterialCVUsingInBOM(string characteristicsValueId)
        {
            try
            {
                var sql = @"IF EXISTS(SELECT 1 FROM( SELECT FGFirstCharacteristicsValueId,FGSecondCharacteristicsValueId,
							RMFirstCharacteristicsValueId,RMSecondCharacteristicsValueId
							FROM dbo.BOMSKUMapping) A 
							WHERE ISNULL(FGFirstCharacteristicsValueId,'')='" + characteristicsValueId + @"' OR ISNULL(FGSecondCharacteristicsValueId,'')='" + characteristicsValueId + @"' 
							OR ISNULL(RMFirstCharacteristicsValueId,'')='" + characteristicsValueId + @"' OR ISNULL(RMSecondCharacteristicsValueId,'')='" + characteristicsValueId + @"'
							) SELECT 1 ELSE SELECT 0 RETURN ";
                return Convert.ToBoolean(_materialMasterRepository.SqlQuery<int>(sql).Single());
            }
            catch (Exception)
            {
                return false;
            }
        }

