        public void UpdateGraph(MaterialMaster entity
           , IEnumerable<MaterialMasterAlternativeUOM> materialMasterAlternativeUOM
           //, IEnumerable<SubMaterial> subMaterialList
           , IEnumerable<MaterialAttributeViewModel> materialMasterAttribute
           , IEnumerable<MaterialAttributeValue> attributeValueList
           , IEnumerable<MaterialMasterCharacteristics> materialMasterCharacteristics
           , IEnumerable<CharacteristicsValue> characteristicsValue
           , IEnumerable<MaterialMasterProcessRouting> materialMasterProcessRouting
           , IEnumerable<MaterialMasterProcessSet> masterProcessSetList
           , IEnumerable<MaterialMasterBusinessProcess> businessProcesses
           , IEnumerable<MaterialMasterRevenueBudget> revenuList)
        {
            var flag = false;
            try
            {
                if (Any(r => r.Id == entity.Id && r.BaseUOMId != entity.BaseUOMId))
                {
                    if (CheckBaseUomIdUse(entity.Id))
                        throw new CustomException("Already characteristics uom factor exist, you can't change base uom!");
                }


                var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
                CheckUnique(entity, identity.CompanyGroupId);
                _unitOfWork.BeginTransaction();
                flag = true;
                //entity.Code = GetCode(entity.MaterialTypeId, entity.Code);

                #region Business process and revenue budget

                foreach (var item in businessProcesses)
                {
                    if (item.Flag && item.Id == 0)
                        BusinessProcessInsertGraph(entity, item);
                    else if (!item.Flag && item.Id != 0)
                        _businessProcessRepository.Delete(item);
                }
                BusinessProcessDeleteGraph(entity.Id, revenuList);
                if (revenuList != null)
                {
                    foreach (var item in revenuList)
                    {
                        RevenueBudgetInsertGraph(entity, item);
                    }
                }

                #endregion Business process and revenue budget

                base.UpdateGraph(entity);

                //MaterialMasterAlternativeUOM
                _materialMasterAlternativeUOM.Insert(materialMasterAlternativeUOM, entity.Id);
                // attribute
                var rdBuilder = new StringBuilder();
                InsertUpdateOrDeleteGraphAttribute(entity, materialMasterAttribute, rdBuilder);
                // attribute value
                _attributeValueService.InsertUpdateOrDeleteFromMaterial(attributeValueList, materialMasterAttribute, entity.CompanyGroupId, entity.Id, rdBuilder);

                //MaterialMasterProcessRouting
                ProsessRouting(entity.Id, materialMasterProcessRouting);

                //CharacteristicsValue//
                InsertUpdateOrDeleteGraphCharacteristics(entity, materialMasterCharacteristics);
                //CharacteristicsValue
                _characteristicsValueService.InsertUpdateOrDeleteFromMaterial(characteristicsValue, entity.CompanyGroupId, entity.Id);
                //Process//
                _masterProcessSetListService.InsertOrUpdateGraph(entity.Id, masterProcessSetList);
                if (rdBuilder.Length > 0 && rdBuilder.IsNotNull())
                    _sqlRepository.ExecuteSqlCommand(rdBuilder.ToString());
                _unitOfWork.SaveChanges();
                flag = false;
                _unitOfWork.Commit();
            }
            catch (CustomException)
            {
                throw;
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Material.ToString()));
            }
            finally
            {
                if (flag)
                    _unitOfWork.Rollback();
            }
        }

        public override void Archive(string key)
        {
            var flag = false;
            try
            {
                if (CheckBaseUomIdUse(key))
                    throw new CustomException("Already characteristics uom factor exist, you can't delete....!");
                _unitOfWork.BeginTransaction();
                flag = true;
                _materialMasterUsageService.DeleteGraph(key);
                _materialMasterAlternativeUOM.DeleteGraph(key);
                _materialMasterProcessRouting.DeleteGraph(key);

                _attributeValueService.DeleteGraphByMaterial(key);
                DeleteGraphAttribute(key);

                _characteristicsValueService.DeleteGraphFromMaterial(key);
                DeleteGraphCharacteristics(key);

                _masterProcessSetListService.DeleteGraph(key);
                var businessProcessList = _businessProcessRepository.Query(t => t.MaterialMasterId == key).Select().ToList();
                foreach (var item in businessProcessList)
                {
                    _businessProcessRepository.Delete(item);
                }

                base.DeleteGraph(key);
                _unitOfWork.SaveChanges();
                flag = false;
                _unitOfWork.Commit();
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Material.ToString()));
            }
            finally
            {
                if (flag)
                    _unitOfWork.Rollback();
            }
        }

