        public GridModel GetMaterialMasterDeterminateGL(GridParameter parameters, string companyId)
        {
            try
            {
                parameters.CmdText = @"SELECT BM.Id,BMA.ActivityId AssetActivityId,A.UserName AssetActivityName, FAMT.FixedAssetMasterId, FAM.UserName AS FixedAssetMasterName, BM.BudgetCategoryId, BM.BudgetSubCategoryId, B.UserName AS BudgetName, BC.UserName AS BudgetCategory, BSC.UserName AS BudgetSubCategory
                                    , AB.UserName AS ACUBudgetName, GI.Id AssetGLId, GI.AccountCode+' - '+GI.UserName AS AssetGLName, FAD.AccumulatedDepreciationGLId, GL1.AccountCode+' - '+GL1.UserName AS AccDepreciation, GL1.UserName AS AccDepreciationName
                                    ,  FAD.AccumulatedDepreciationBudgetMasterId,FAD.AccumulatedDepreciationActivityId,AC.UserName AccumulativeActivityName, BM.RefNo
                                    FROM MST.BudgetMaster AS BM
                                    LEFT JOIN [HKP].[Budget] B ON BM.BudgetId=B.Id
									LEFT JOIN MST.BudgetMasterActivity BMA ON BM.Id=BMA.BudgetMasterId
									LEFT JOIN HKP.Activity A ON BMA.ActivityId=A.Id
                                    LEFT JOIN [HKP].[BudgetCategory] BC ON BM.BudgetCategoryId=BC.Id
                                    LEFT JOIN [HKP].[BudgetSubCategory] BSC ON BM.BudgetSubCategoryId=BSC.Id
                                    LEFT JOIN [HKP].[GLGeneralInfo] GI ON BM.GLGeneralInfoId=GI.Id
                                    LEFT JOIN [HKP].[GLAccountType] AS GLAT ON GLAT.GLGeneralInfoId=GI.Id
                                    LEFT JOIN [HKP].[FixedAssetMasterBudgetTag] FAMT ON BM.Id=FAMT.BudgetMasterId
                                    LEFT JOIN [MST].[FixedAssetMaster] FAM ON FAMT.FixedAssetMasterId=FAM.Id
                                    LEFT JOIN [HKP].[FixedAssetMasterGL] AS FAD ON FAD.FixedAssetMasterId=FAMT.FixedAssetMasterId
                                    LEFT JOIN [HKP].[GLGeneralInfo] AS GL1 ON GL1.Id=FAD.AccumulatedDepreciationGLId
                                    LEFT JOIN [MST].[BudgetMaster] ABM ON FAD.AccumulatedDepreciationBudgetMasterId=ABM.Id
                                    LEFT JOIN [HKP].[Budget] AB ON ABM.BudgetId=AB.Id
									LEFT JOIN HKP.Activity AC ON FAD.AccumulatedDepreciationActivityId = AC.Id
                                    LEFT JOIN [ORG].[Company] AS COM ON COM.COAId=bm.COAId
                                    LEFT JOIN [HKP].[COA] AS C ON C.Id=com.COAId
                                    WHERE GLAT.AccountType='Asset' AND COM.Id='" + companyId + "'";
                return _sqlRepository.GetGridData(parameters);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Material.ToString()));
            }
        }

        public GridModel GetMaterialMasterWithFixedAssetMasterId(GridParameter parameters, string fixedAssetMasterId)
        {
            try
            {
                parameters.CmdText = @"SELECT A.Id, A.UserName, A.ShortName, A.StandardName, A.[Sequence], A.Code, U.UserName BaseUOMName 
                                       FROM [MST].[MaterialMaster] A
                                       LEFT JOIN SCS.UnitOfMeasurement U ON A.BaseUOMId=U.Id
                                       LEFT JOIN MST.BudgetMaster AS BM ON A.BudgetMasterId=BM.Id
                                       LEFT JOIN HKP.FixedAssetMasterBudgetTag AS FAMT ON FAMT.BudgetMasterId=BM.Id
                                       LEFT JOIN [MST].[FixedAssetMaster] AS FAM ON FAMT.FixedAssetMasterId=FAM.Id
                                       WHERE FAM.Id='" + fixedAssetMasterId + "' And A.IsAsset=1";
                return _sqlRepository.GetGridData(parameters);
            }
            catch (Exception)
            {
                throw;
            }
        }

        public GridModel GetMaterialMasterWithFixedAssetMaster(GridParameter parameters)
        {
            try
            {
                parameters.CmdText = @"SELECT MT.UserName MaterialTypeName, MGP.UserName AS MaterialGroupMasterName, MM.Id, FAM.Id FixedAssetMasterId, MM.UserName, MM.ShortName, MM.StandardName, BM.GLGeneralInfoId, AGL.UserName AS AssetGLName, BM.GLGeneralInfoId AS AssetGLId, FAMT.BudgetMasterId
                                    , BM.BudgetId, B.UserName AssetBudgetName, MM.Sequence, MM.Code, U.UserName AS BaseUOMName, FAM.UserName AS AssetMasterName, FAM.AssetType, MMA.CountId AS HasArticle, AC.UserName AS ActivityName
                                    , AC.Id ActivityId, BM.RefNo, FAC.UserName FixedAssetCategory, FASC.UserName AS FixedAssetSubCategory,MM.IsOriginApplicable
									, MM.WithSKU, ISNULL(ART.HasAttribute,CAST(0 AS BIT)) AS HasAttribute
                                    FROM [MST].[MaterialMaster] AS MM
                                    LEFT JOIN [MST].[MaterialGroupMaster] AS MGP ON MGP.Id=MM.MaterialGroupMasterId
                                    LEFT JOIN [HKP].[MaterialType] AS MT ON MT.Id=MGP.MaterialTypeId
                                    LEFT JOIN [MST].[BudgetMaster] AS BM ON BM.Id=MM.BudgetMasterId
                                    LEFT JOIN [HKP].[GLGeneralInfo] AS AGL ON AGL.Id=BM.GLGeneralInfoId
                                    LEFT JOIN [HKP].[Budget] AS B ON B.Id=BM.BudgetId
                                    LEFT JOIN [HKP].[Activity] AS AC ON AC.Id=MM.ActivityId
                                    LEFT JOIN [HKP].[FixedAssetMasterBudgetTag] AS FAMT ON FAMT.BudgetMasterId=BM.Id AND FAMT.BudgetMasterId=MM.BudgetMasterId
                                    LEFT JOIN [MST].[FixedAssetMaster] AS FAM ON FAM.Id=FAMT.FixedAssetMasterId
                                    LEFT JOIN [HKP].[FixedAssetCategory] FAC ON FAM.FixedAssetCategoryId=FAC.Id
                                    LEFT JOIN [HKP].[FixedAssetSubCategory] FASC ON FAM.FixedAssetSubCategoryId=FASC.Id
                                    LEFT JOIN [SCS].[UnitOfMeasurement] AS U ON MM.BaseUOMId=U.Id
                                    LEFT JOIN (SELECT COUNT(Id) CountId, MaterialMasterId FROM [MST].[MaterialMasterArticle] GROUP BY MaterialMasterId) MMA ON MM.Id=MMA.MaterialMasterId 
									LEFT JOIN (SELECT AttributeSetLength=CASE WHEN COUNT(MaterialMasterId)>0THEN COUNT(MaterialMasterId) ELSE 0 END
                                                , HasAttribute=CASE WHEN COUNT(MaterialMasterId)>0 THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END, MaterialMasterId
                                            FROM MST.MaterialMasterAttribute GROUP BY MaterialMasterId) AS ART ON ART.MaterialMasterId=MM.Id
                                    WHERE MM.IsAsset=1 AND MM.Active=1";
                return _sqlRepository.GetGridData(parameters);
            }
            catch (Exception)
            {
                throw;
            }
        }

