        #region Material Master Attribute

        private void InsertGraphAttribute(MaterialMaster entity, IEnumerable<MaterialAttributeViewModel> viewModel)
        {
            foreach (var item in viewModel)
            {
                if (item.CreationLevel != "Material")
                {
                    InsertAttribute(entity, item, null);
                }
                else
                {
                    item.CompanyGroupId = entity.CompanyGroupId;
                    _attributeService.InsertOrUpdate(item);
                    InsertAttribute(entity, item, null);
                }
            }
        }

        private void InsertAttribute(MaterialMaster entity, MaterialAttributeViewModel item, IEnumerable<MaterialMasterAttributeValue> dbList)
        {
            var materialAttr = new MaterialMasterAttribute
            {
                Id = _pkGeneratorService.GetAutoNumber(nameof(MaterialMasterAttribute), PKGeneratorEnum.Auto, null, DateTime.Now),
                MaterialMasterId = entity.Id,
                //MaterialGroupMasterId = entity.MaterialGroupMasterId,
                MaterialAttributeId = item.MaterialAttributeId,
                Sequence = item.Sequence,
                IsFreeField = item.IsFreeField,
                IsPreDefinedField = item.IsPreDefinedField,
                IsMandatory = item.IsMandatory,
                Active = true
            };
            AuditService.AddedLog(materialAttr);
            _attributeRepository.Insert(materialAttr);
        }

        private void InsertUpdateOrDeleteGraphAttribute(MaterialMaster entity, IEnumerable<MaterialAttributeViewModel> materialMasterAttribute, StringBuilder rdBuilder)
        {
            //var db_AttrList = _attributeRepository.Query(t => t.MaterialMasterId == entity.Id).Select().ToList();
            var db_AttrList = _attributeRepository.SqlQuery<MaterialAttributeViewModel>(@"SELECT A.Id, A.MaterialMasterId, A.MaterialAttributeId, B.CreationLevel
                                                                                            FROM [MST].[MaterialMasterAttribute] AS A
                                                                                            LEFT JOIN [HKP].[MaterialAttribute] AS B ON A.MaterialAttributeId=B.Id
                                                                                            WHERE A.MaterialMasterId='" + entity.Id + "'").ToList();
            if (materialMasterAttribute != null && materialMasterAttribute.Count() > 0)
            {
                foreach (var item in materialMasterAttribute)
                {
                    if (string.IsNullOrEmpty(item.Id))
                    {
                        if (item.CreationLevel != "Material")
                        {
                            InsertAttribute(entity, item, null);
                        }
                        else
                        {
                            item.CompanyGroupId = entity.CompanyGroupId;
                            _attributeService.InsertOrUpdate(item);
                            InsertAttribute(entity, item, null);
                        }
                    }
                    else
                    {
                        item.CompanyGroupId = entity.CompanyGroupId;
                        _attributeService.InsertOrUpdate(item);

                        var data = _attributeRepository.Find(item.Id);
                        data.Sequence = item.Sequence;
                        data.IsFreeField = item.IsFreeField;
                        data.IsPreDefinedField = item.IsPreDefinedField;
                        data.IsMandatory = item.IsMandatory;
                        data.JoiningSequence = item.JoiningSequence;
                        data.JoiningParameter = item.JoiningParameter;
                        AuditService.UpdatedLog(data);
                        _attributeRepository.Update(data);

                    }
                }
            }
            if (db_AttrList != null && db_AttrList.Count() > 0)
            {

                var builderSql = "";
                foreach (var item in db_AttrList)
                {
                    if (!materialMasterAttribute.Any(t => t.Id == item.Id))
                    {
                        if (item.CreationLevel == "Material")
                        {
                            //_attributeService.DeleteGraph(item.MaterialAttributeId);
                            builderSql += @"DELETE HKP.CompanyGroupMaterialAttribute WHERE MaterialAttributeId='" + item.MaterialAttributeId + "';";
                            builderSql += @"DELETE HKP.MaterialAttribute WHERE Id='" + item.MaterialAttributeId + "';";
                            //rdBuilder.Append(builderSql);
                            rdBuilder.Insert(0, builderSql);
                        }
                        builderSql = @"DELETE MST.MaterialMasterAttribute WHERE Id='" + item.Id + "';";
                        rdBuilder.Insert(0, builderSql);
                        builderSql = "";
                    }
                }

            }
        }

        public IEnumerable<object> GetMaterialMasterAttribute(string masterId)
        {
            try
            {
                var _sql = @"SELECT A.Id, A.MaterialMasterId, --A.MaterialGroupMasterId, 
                                 A.MaterialAttributeId, A.[Sequence], A.Active, A.Archive
	                             , B. Code, B.ShortName, B.StandardName, B.UserName, B.Remarks, B.[Description], B.CreationLevel
	                             , A.IsFreeField, A.IsPreDefinedField, A.IsMandatory, B.ValueAssignmentLevel, B.UserName, B.AttributeProperty, B.IsFixedNoOfCharacter, B.NoOfCharacter
	                             , '' AS MaterialMasterAttributeValues,A.JoiningSequence,A.JoiningParameter
                    FROM [MST].[MaterialMasterAttribute] AS A
                    INNER JOIN [HKP].[MaterialAttribute] AS B ON A.MaterialAttributeId=B.Id
                    WHERE A.MaterialMasterId='" + masterId + "' ORDER BY A.Sequence";
                return _sqlRepository.GetDataCollection(_sql, null);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Material.ToString()));
            }
        }

        public IEnumerable<object> GetMaterialMasterAttributeList(string materialMasterId)
        {
            try
            {
                var _sql = @"SELECT NULL AS Id
                                    , MMA.MaterialMasterId
                                    , MMA.MaterialAttributeId AS MaterialAttributeId
                                    , MA.UserName AS MaterialAttributeName
                                    , MMA.IsFreeField
                                    , MMA.IsPreDefinedField
                                    , MMA.IsMandatory
                                    , MA.ValueAssignmentLevel
                                    , NULL AS MaterialMasterArticleId
		                            , MAV.Id AS MaterialAttributeValueId
		                            , MaterialAttributeValueFreeText =CASE WHEN (MAV.IsDefault = 1) THEN MAV.UserName ELSE NULL END
                                    ,MMA.JoiningSequence, MMA.JoiningParameter
                            FROM MST.MaterialMasterAttribute AS MMA
                            LEFT JOIN HKP.MaterialAttribute AS MA ON MMA.MaterialAttributeId = MA.Id
                            LEFT JOIN (SELECT * FROM HKP.MaterialAttributeValue WHERE Active = 1 AND IsDefault = 1) AS MAV ON MAV.MaterialAttributeId=MMA.MaterialAttributeId AND MAV.SourceType=MA.ValueAssignmentLevel
                            WHERE MMA.MaterialMasterId = '" + materialMasterId + "' ORDER BY MMA.JoiningSequence";
                return _sqlRepository.GetDataCollection(_sql, null);
            }
            catch (Exception)
            {
                throw;
            }
        }

        private void DeleteGraphAttribute(string masterId)
        {
            try
            {
                var dbList = _attributeRepository.SqlQuery<MaterialAttributeViewModel>(@"SELECT A.Id, A.MaterialMasterId, A.MaterialAttributeId, B.CreationLevel
                                                                                            FROM [MST].[MaterialMasterAttribute] AS A
                                                                                            LEFT JOIN [HKP].[MaterialAttribute] AS B ON A.MaterialAttributeId=B.Id
                                                                                            WHERE A.MaterialMasterId='" + masterId + "'").ToList();
                foreach (var item in dbList)
                {
                    _attributeRepository.Delete(item.Id);
                    if (item.CreationLevel == "Material")
                        _attributeService.DeleteGraph(item.MaterialAttributeId);
                }

            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Material.ToString()));
            }
        }

