        private void BusinessProcessDeleteGraph(string masterId, IEnumerable<MaterialMasterRevenueBudget> entities)
        {
            var dBData = _budgetRepository.Query(t => t.MaterialMasterId == masterId).Select().ToList();
            if (dBData != null)
            {
                if (entities == null)
                {
                    foreach (var item in dBData)
                    {
                        _budgetRepository.Delete(item);
                    }
                }
                else
                {
                    foreach (var item in dBData)
                    {
                        if (!entities.Any(t => t.Id == item.Id))
                            _budgetRepository.Delete(item);
                    }
                }
            }
        }

