        #region Prosess Routing

        private void ProsessRouting(string materialMasterId, IEnumerable<MaterialMasterProcessRouting> processRouting)
        {
            if (processRouting != null)
            {
                var count = _materialMasterRepository.SqlQuery<int>($"SELECT ISNULL(MAX(CAST(RIGHT(Id, 2) AS INT)), 0) Id FROM [MST].[MaterialMasterProcessRouting] WHERE MaterialMasterId='{materialMasterId}'").First();
                foreach (var item in processRouting)
                {
                    if (item.Flag && string.IsNullOrEmpty(item.MaterialMasterId))
                    {
                        //Process routing was checked(IsLocked not map with db)
                        count++;
                        item.Id = MakePK(materialMasterId, count, 2);
                        item.MaterialMasterId = materialMasterId;
                        item.Active = true;
                        _materialMasterProcessRouting.InsertGraph(item);
                    }
                    else if (!item.Flag && !string.IsNullOrEmpty(item.Id))//previous saved
                        _materialMasterProcessRouting.Delete(item);
                }
            }
        }

