        private void InsertUpdateOrDeleteGraphCharacteristics(MaterialMaster entity, IEnumerable<MaterialMasterCharacteristics> characteristics)
        {
            if (entity.WithSKU && characteristics == null && characteristics.Count() == 0) throw new CustomException("Please define characteristics.");

            var dbCharacList = _characteristicsRepository.Query(t => t.MaterialMasterId == entity.Id).Select().ToList();

            if (characteristics != null && characteristics.Count() > 0)
            {
                foreach (var item in characteristics)
                {
                    if (string.IsNullOrEmpty(item.Id))
                        InsertCharacteristics(entity, item);
                    else
                    {
                        AuditService.UpdatedLog(item);
                        _characteristicsRepository.Update(item);
                    }
                }
            }
            if (dbCharacList != null)
            {
                foreach (var item in dbCharacList)
                {

                    if (!characteristics.Any(t => t.Id == item.Id))
                        //if (CheckMaterialMasterCharacteristicsUsingInBOM(item.CharacteristicsId))
                        //	throw new CustomException("This Characteristics is already used in BOM, you can't change!");
                        _characteristicsRepository.Delete(item);
                }
            }
        }

