        private bool CheckBaseUomIdUse(string id)
        {
            var sql = "DECLARE @baseUOMId VARCHAR(10) " +
                            $"SELECT @baseUOMId = BaseUOMId FROM [{DbSchema.Masters}].[{DbTable.MaterialMaster}] WHERE Id = '{id}' " +
                            $" IF EXISTS(SELECT 1 FROM (  " +
                            $"SELECT BaseUOMId AS CheckingColumn FROM [{DbSchema.Masters}].[{DbTable.CharacteristicsWisePropertiesUOMFactor}] WHERE Archive= 0 " +
                            $" ) A WHERE CheckingColumn=@baseUOMId ) SELECT 1 ELSE SELECT 0 RETURN ";
            return Convert.ToBoolean(_materialMasterRepository.SqlQuery<int>(sql).Single());
        }

