        /// <summary>
        /// If material type IsCodeAutoGenerate true then material type code will be auto generate.
        /// </summary>
        /// <param name="materialTypeId"></param>
        /// <param name="code"></param>
        /// <returns></returns>
        private string GetCode()
        {
            var count = _attributeRepository.SqlQuery<int>("SELECT ISNULL(MAX(CAST(SUBSTRING(Code, 5, (LEN(Code)-4)) AS INT)), 0) AS Code FROM [MST].[MaterialMaster] WHERE Code LIKE '" + DateTime.Now.Year + "%'").First();
            count++;
            var code = DateTime.Now.Year.ToString() + count.ToString();
            return code;
        }

        public IEnumerable<object> GetUomCboByMaterialMaster(string[] id)
        {
            var _sql = @"SELECT DISTINCT UoM.Id AS [Value], 1 AS IsBaseUom, UoM.UserName AS [Text], MM.Id AS MaterialMasterId, 1 AS BaseUoMFactor
                    FROM SCS.unitofmeasurement AS UoM INNER JOIN MST.MaterialMaster MM ON MM.BaseUoMId = UoM.Id
                    WHERE UoM.Archive=0 AND MM.Id IN(" + ReturnStringArray(id) + @")
                    UNION
                    SELECT UoM.Id AS [Value], 0 AS IsBaseUom, UoM.UserName AS [Text], MM.Id AS MaterialMasterId, 1 AS BaseUoMFactor
                    FROM SCS.unitofmeasurement AS UoM INNER JOIN MST.MaterialMaster MM ON MM.PurchaseOrderUOMId = UoM.Id AND MM.BaseUoMId<>MM.PurchaseOrderUOMId
                    WHERE UoM.Archive=0 AND MM.Id IN(" + ReturnStringArray(id) + @") AND UoM.Id NOT IN(SELECT AlternativeUOMId FROM [MST].[MaterialMasterAlternativeUOM] WHERE MaterialMasterId = MM.Id)
                    UNION
                    SELECT UoM.Id AS [Value], 0 AS IsBaseUom, UoM.UserName AS [Text], MM.Id AS MaterialMasterId, 1 AS BaseUoMFactor
                    FROM SCS.unitofmeasurement AS UoM INNER JOIN MST.MaterialMaster MM ON MM.SalesOrderUOMId = UoM.Id AND MM.BaseUoMId<>MM.SalesOrderUOMId
                    WHERE UoM.Archive=0 AND MM.Id IN(" + ReturnStringArray(id) + @") AND UoM.Id NOT IN(SELECT AlternativeUOMId FROM [MST].[MaterialMasterAlternativeUOM] WHERE MaterialMasterId = MM.Id)
                    UNION
                    SELECT UoM.Id AS [Value], 0 AS IsBaseUom, UoM.UserName AS [Text], MMUoM.MaterialMasterId, BaseUoMFactor
                    FROM SCS.unitofmeasurement AS UoM INNER JOIN(SELECT * FROM[MST].[MaterialMasterAlternativeUOM]
                    WHERE  MaterialMasterId IN(" + ReturnStringArray(id) + @")) AS MMUoM ON MMUoM.AlternativeUoMId = UoM.Id
                    WHERE UoM.Archive = 0";
            return _sqlRepository.GetDataCollection(_sql);
        }

        public IEnumerable<object> GetCharacteristicsByMaterialMasterId(string materialMasterId)
        {
            var _sql = @"SELECT MMC.CharacteristicsId AS [Value], C.UserName AS [Text], MMC.MaterialMasterId, MMC.IsFreeField, MMC.IsPreDefinedField, MMC.IsMandatory, C.ValueAssignmentLevel, MMC.[Sequence]
	                            , CharacteristicsValueId = CASE WHEN (CV.MaterialMasterId IS NULL AND CV.IsDefault=1) THEN CV.Id
									WHEN (CV.MaterialMasterId<>'' AND MMCV.IsDefault=1) THEN MMCV.Id ELSE NULL END
	                            , [FreeText] =CASE WHEN (CV.MaterialMasterId IS NULL AND CV.IsDefault=1) THEN CV.UserName
					                                WHEN (CV.MaterialMasterId<>'' AND MMCV.IsDefault=1) THEN MMCV.UserName ELSE NULL END
						                            , 0 AS FlagDisable
                            FROM MST.MaterialMasterCharacteristics AS MMC
                            JOIN HKP.Characteristics C ON MMC.CharacteristicsId=C.Id
                            LEFT JOIN (SELECT * FROM HKP.CharacteristicsValue WHERE Active=1 AND IsDefault=1 AND MaterialMasterId='" + materialMasterId + @"') AS CV ON CV.CharacteristicsId=MMC.CharacteristicsId AND CV.CharacteristicsId=C.Id
                            LEFT JOIN (SELECT * FROM HKP.CharacteristicsValue WHERE Active=1 AND IsDefault=1 AND MaterialMasterId='" + materialMasterId + @"') AS MMCV ON MMCV.MaterialMasterId=MMC.MaterialMasterId AND MMCV.CharacteristicsId=C.Id
                            WHERE MMC.MaterialMasterId='" + materialMasterId + "' ORDER BY MMC.[Sequence]";
            return _sqlRepository.GetDataCollection(_sql, null);
        }

