        public GridModel MaterialMasterSearch(GridParameter parameters, string companyGroupId)
        {
            parameters.CmdText = @"SELECT MT.UserName AS MaterialType
	                                , MGP.UserName AS MaterialGroupMaster
	                                , MM.Id, MM.Code, MM.UserName, MM.StandardName, MM.ShortName, MM.[Description]
	                                --, MM.MaterialGridId, MG.[Description] AS GridName
                                    --, bs.UserName BuyerStyle,b.UserName Buyer, bs.BuyerId, mm.OurStyleId
	                                , PM.UserName AS ProductMaster
	                                , MM.BaseUOMId, UOMB.UserName AS BaseUom
                                FROM[MST].[MaterialMaster] AS MM
                                
                                --LEFT OUTER JOIN [HKP].[MaterialTypeNature] AS MTN ON MTN.MaterialTypeId = MT.Id
                                LEFT OUTER JOIN [MST].[MaterialGroupMaster] AS MGP ON MM.MaterialGroupMasterId = MGP.Id
								LEFT OUTER JOIN [HKP].[MaterialType] AS MT ON MGP.MaterialTypeId = MT.Id
                                --LEFT OUTER JOIN [HKP].[MaterialGrid] AS MG ON MM.MaterialGridId = MG.Id
                                LEFT OUTER JOIN [MST].[ProductMaster] AS PM ON MM.ProductMasterId = PM.Id
                                LEFT OUTER JOIN [SCS].[UnitOfMeasurement] AS UOMB ON MM.BaseUOMId = UOMB.Id
                                --LEFT OUTER JOIN hkp.BuyerStyle bs ON bs.OurStyleId = MM.OurStyleId
                                --LEFT OUTER JOIN hkp.Buyer b ON b.Id = bs.BuyerId
                                WHERE MM.CompanyGroupId = '" + companyGroupId + @"'
                                AND MM.Archive = 0 AND MM.Active = 1 --AND MTN.Nature = '" + EnumMaterialTypeNatureList.FinishedGoods + @"'";
            return _sqlRepository.GetGridData(parameters);
        }

        public GridModel MaterialSearchByBusinessProcess(GridParameter parameters, string groupId, string type)
        {
            var sql = "";
            if (!string.IsNullOrEmpty(type) && type != "null")
                sql = @"AND MM.Id IN(SELECT MBP.MaterialMasterId FROM [MST].[MaterialMasterBusinessProcess] AS MBP
                        LEFT JOIN [SCS].[BusinessProcess] AS BP ON MBP.BusinessProcessId = BP.Id
                        WHERE BP.BusinessProcessName ='" + type + "')";

            parameters.CmdText = @"SELECT DISTINCT MM.MaterialGroupMasterId, MM.HSNCodeId, MGP.UserName AS MaterialGroupMasterName, MT.UserName AS MaterialTypeName, MM.Id ,MM.Code ,MM.UserName, MM.StandardName, MM.ShortName
                                        , MM.BaseUOMId, UOMB.UserName AS BaseUoM, PM.UserName AS ProductMasterName
                                        , OS.UserName AS OurStyleName, MM.WithSKU, ISNULL(ART.HasAttribute,CAST(0 AS BIT)) AS HasAttribute
                                        , hasInventory=CASE WHEN IM.Id<>'' THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END, MM.IsOriginApplicable
                                        , FAMT.FixedAssetMasterId AS AssetMasterId,FAM.UserName AS AssetMasterName, FAM.AssetType, MM.BudgetMasterId, B.UserName AS AssetBudgetCode, MM.ActivityId, ACT.UserName AS ActivityName
                                        , IsAsset=CASE WHEN MM.IsAsset=0 THEN 'No' ELSE 'Yes' END
                                FROM [MST].[MaterialMaster] AS MM
                                LEFT JOIN [TRN].ProductDefinition AS PD ON PD.MaterialMasterId= MM.Id
                                LEFT JOIN [MST].[MaterialGroupMaster] AS MGP ON MM.MaterialGroupMasterId = MGP.Id
                                LEFT JOIN[HKP].[MaterialType] AS MT ON MGP.MaterialTypeId = MT.Id
                                LEFT JOIN [MST].[ProductMaster] AS PM ON PD.ProductMasterId = PM.Id
                                LEFT JOIN hkp.ProductCategory pc on pc.Id=pm.ProductCategoryId
                                LEFT JOIN hkp.ProductSubCategory psc on psc.Id=pm.ProductSubCategoryId
                                LEFT JOIN [SCS].[UnitOfMeasurement] AS UOMB ON MM.BaseUOMId = UOMB.Id
                                LEFT JOIN [HKP].OurStyle AS OS ON PD.OurStyleId= OS.Id
                                LEFT JOIN (SELECT AttributeSetLength=CASE WHEN COUNT(MaterialMasterId)>0THEN COUNT(MaterialMasterId) ELSE 0 END
                                                , HasAttribute=CASE WHEN COUNT(MaterialMasterId)>0 THEN CAST(1 AS BIT) ELSE CAST(0 AS BIT) END, MaterialMasterId
                                            FROM MST.MaterialMasterAttribute GROUP BY MaterialMasterId) AS ART ON ART.MaterialMasterId=MM.Id
                                LEFT JOIN TRN.InventoryMaterial AS IM ON IM.MaterialMasterId=MM.Id
                                LEFT JOIN MST.BudgetMaster AS BM ON MM.BudgetMasterId=BM.Id
                                LEFT JOIN HKP.Budget AS B ON B.Id=BM.BudgetId
                                LEFT JOIN HKP.FixedAssetMasterBudgetTag AS FAMT ON FAMT.BudgetMasterId=BM.Id
                                LEFT JOIN [MST].[FixedAssetMaster] AS FAM ON FAMT.FixedAssetMasterId=FAM.Id
                                LEFT JOIN HKP.Activity AS ACT ON MM.ActivityId=ACT.Id
                                WHERE MM.CompanyGroupId='" + groupId + @"' AND MM.Archive=0 AND MM.Active=1 " + sql;
            return _sqlRepository.GetGridData(parameters);
        }




