        public IEnumerable<object> GetMaterialMaster(string salesordermasterid)
        {
            try
            {
                var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
                var sql = "SELECT CONCAT(MM.Code,'-' , MM.UserName) AS [Text], " +
                                          "MGP.UserName AS MaterialGroupMaster, " +
                                          "MM.Code, " +
                                          "MM.UserName, " +
                                          "MG.[Description] AS GridName, " +
                                          "PM.UserName AS ProductMaster, " +
                                          "UOMB.UserName AS BaseUom, " +
                                          "MM.StandardName, " +
                                          "MM.ShortName, " +
                                          "MM.[Description], " +
                                          "MM.Id [Value], " +
                                          "MM.MaterialGridId, " +
                                          "MM.BaseUOMId " +
                                   $"FROM [{DbSchema.Masters}].[{DbTable.MaterialMaster}] AS MM  " +
                                   $"LEFT OUTER JOIN [HKP].[{DbTable.MaterialType}] AS MT ON MM.MaterialTypeId = MT.Id " +
                                   $"LEFT OUTER JOIN [{DbSchema.Masters}].[{DbTable.MaterialGroupMaster}] AS MGP ON MM.MaterialGroupMasterId = MGP.Id " +
                                   $"LEFT OUTER JOIN [HKP].[{DbTable.MaterialGrid}] AS MG ON MM.MaterialGridId = MG.Id " +
                                   $"LEFT OUTER JOIN [{DbSchema.Masters}].[{DbTable.ProductMaster}] AS PM ON MM.ProductMasterId = PM.Id " +
                                   $"INNER JOIN [{DbSchema.SystemConfigurationAndSetup}].[UnitOfMeasurement] AS UOMB ON MM.BaseUOMId = UOMB.Id  " +
                                   $"WHERE MM.CompanyGroupId = '{identity.CompanyGroupId}' AND MM.Archive = 0 AND MM.Active = 1 AND MM.Id in (select MaterialMasterId from  " +
                                    $" [{DbSchema.Transaction}].[{DbTable.SalesOrderMaterialMaster}]  where SalesOrderMasterId='" + salesordermasterid + "') ";

                return _sqlRepository.GetDataCollection(sql, null);
            }
            catch (Exception)
            {
                throw;
            }
        }

