        public IEnumerable<object> GetRevenueBudget(string materialMasterId)
        {
            try
            {
                var sql = @"SELECT BM.Id AS BudgetMasterId, GLGI.Id AS GLGeneralInfoId, GLGI.UserName AS GLItem
	                              , GLGI.AccountCode, BG.UserName AS BudgetGroup, BC.UserName AS BudgetCategory, BSC.UserName AS BudgetSubCategory
	                              , BCL.UserName AS BudgetClass, B.Id AS BudgetId, B.Code AS BudgetCode , B.UserName as BudgetName
                            FROM MST.MaterialMasterRevenueBudget AS MR
                            INNER JOIN MST.BudgetMaster AS BM  ON MR.BudgetMasterId=BM.Id
                            INNER JOIN HKP.GLGeneralInfo AS GLGI ON BM.GLGeneralInfoId=GLGI.Id
                            LEFT OUTER JOIN HKP.BudgetGroup AS BG ON BG.Id=BM.BudgetGroupId
                            LEFT OUTER JOIN HKP.BudgetCategory AS BC ON BC.Id=BM.BudgetCategoryId
                            LEFT OUTER JOIN HKP.BudgetSubCategory AS BSC ON BSC.Id=BM.BudgetSubCategoryId
                            LEFT OUTER JOIN HKP.BudgetClass AS BCL ON BCL.Id=BM.BudgetClassId
                            INNER JOIN HKP.Budget AS B ON B.Id=BM.BudgetId
                            WHERE MR.MaterialMasterId='" + materialMasterId + "'";
                return _sqlRepository.GetDataCollection(sql, null);
            }
            catch (Exception)
            {
                throw;
            }
        }

