        public GridModel GetCommonMachineListByProcess(GridParameter parameters, string companyGroupId, string[] processIds)
        {
            parameters.CmdText = @"SELECT MGP.UserName AS MaterialGroupMaster, MM.Id AS MaterialMasterId
		                                , MM.Code, MM.ShortName, MM.StandardName,MM.UserName AS MaterialMasterName
                                        , FAM.UserName AS AssetMaster, B.UserName AS BudgetName
                                        , ProsessIds=(SELECT STUFF((SELECT DISTINCT ',' +  ProcessId FROM [MST].[MaterialMasterMachineProcess] WHERE MaterialMasterId=MM.Id FOR XML PATH('')),1,1,''))
                                FROM [MST].[MaterialMaster] AS MM
                                LEFT JOIN [MST].[MaterialGroupMaster] AS MGP ON MM.MaterialGroupMasterId = MGP.Id
                                LEFT JOIN MST.BudgetMaster AS BM ON MM.BudgetMasterId=BM.Id
                                LEFT JOIN HKP.Budget AS B ON B.Id=BM.BudgetId
                                LEFT JOIN HKP.FixedAssetMasterBudgetTag AS FAMT ON FAMT.BudgetMasterId=BM.Id
                                LEFT JOIN [MST].[FixedAssetMaster] AS FAM ON FAMT.FixedAssetMasterId=FAM.Id
                                LEFT JOIN [MST].[MaterialMasterBusinessProcess] AS MMBP ON MMBP.MaterialMasterId=MM.Id
                                LEFT JOIN [SCS].[BusinessProcess] AS BP ON MMBP.BusinessProcessId=BP.Id
                                WHERE MM.CompanyGroupId = '" + companyGroupId + @"' AND MM.Archive = 0 AND MM.Active = 1
                                AND BP.BusinessProcessName='" + BusinessProcessEnum.MachineDefinition + "'";
            return _sqlRepository.GetGridData(parameters);
        }

        public Dictionary<string, object> GetDocFile(string id)
        {
            try
            {
                var sql = @"SELECT Id,Image FROM [MST].[MaterialMaster] WHERE Id='" + id + "'";
                return _sqlRepository.GetData(sql, null);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }

        public void UpdateDocument(string id)
        {
            ExecuteSqlCommand("UPDATE [MST].[MaterialMaster] SET Image=NULL Where Id='" + id + "'");
        }

        public IEnumerable<object> CheckItemArticleSKUList()
        {
            try
            {
                var sql = @"SELECT MM.Id MaterialMasterId,MM.Code,MM.UserName MaterialMasterName
                        ,MMA.Id AS MaterialMasterArticleId,MMA.StandardName ArticleName, IsArticleId=case when MMA.Id<>'' then 1 else 0 end
                        ,ISNULL( MMC.IsSKU,0) IsSKU
                        FROM MST.MaterialMaster MM 
                        LEFT JOIN MST.MaterialMasterArticle MMA ON MMA.MaterialMasterId=MM.Id
                        LEFT JOIN (Select count(CharacteristicsId) AS IsSKU,MaterialMasterId 
                        FROM MST.MaterialMasterCharacteristics GROUP BY MaterialMasterId)
                        MMC ON MMC.MaterialMasterId=MM.Id
                        JOIN(SELECT MaterialMasterId FROM  TRN.MasterOrderItem GROUP BY MaterialMasterId) MOI ON MOI.MaterialMasterId=MM.Id";
                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Party.ToString()));
            }
        }
