        private string MaterialMasterSql2()
        {
            var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
            return @" 
						SELECT
							T.Id as MaterialId,
							T.UserName MaterialType,MGM.UserName MaterialGroup , M.Code,M.UserName Material
							,MC.UserName MaterialCategory, uom.UserName BaseUOM
							,IsAsset=case when M.IsAsset=0 then 'No' else 'Yes' end
							,GL.AccountCode GLCode,GL.UserName GLName
							,BM.RefNo BudgetRefNo,B.UserName BudgetName
							,A.Code ActivityCode,A.UserName AcitivtyName
							,FM.UserName FixedAssetMaster
                            ,MachineDefinition=CASE WHEN BB.BusinessProcessName='MachineDefinition' THEN 'Yes' ELSE 'No' END
						    ,Active = case when M.Active=0 then 'No' else 'Yes' end
							FROM MST.MaterialMaster M
							
							LEFT JOIN [MST].[MaterialGroupMaster] MGM ON M.MaterialGroupMasterid=MGM.id
							LEFT JOIN [HKP].[MaterialType] T ON T.Id=MGM.MaterialTypeId
							LEFT JOIN [HKP].[MaterialCategory] MC ON MC.Id=M.MaterialCategoryId
							LEFT JOIN [HKP].[MaterialSubCategory] SC ON SC.Id=M.MaterialSubCategoryId
							LEFT JOIN HKP.MaterialGroup1 MG ON MG.Id=MGM.MaterialGroup1Id
							LEFT JOIN SCS.UnitOfMeasurement uom ON uom.Id=M.BaseUOMId
							LEFT JOIN MST.BudgetMaster BM ON BM.Id=M.BudgetMasterId
							LEFT JOIN HKP.Budget B ON B.Id=BM.BudgetId
							LEFT JOIN HKP.GLGeneralInfo GL ON GL.Id=BM.GLGeneralInfoId
							LEFT JOIN HKP.Activity A ON A.Id=M.ActivityId
							LEFT JOIN HKP.FixedAssetMasterBudgetTag TAG ON TAG.BudgetMasterId=M.BudgetMasterId
							LEFT JOIN MST.FixedAssetMaster FM ON FM.Id=TAG.FixedAssetMasterId
LEFT JOIN (
SELECT MBP.MaterialMasterId,BP.BusinessProcessName FROM [MST].[MaterialMasterBusinessProcess] AS MBP
LEFT JOIN [SCS].[BusinessProcess] AS BP ON MBP.BusinessProcessId = BP.Id
)BB ON BB.MaterialMasterId=M.Id
							ORDER BY M.UserName";

        }
