        #region BudgetWith FAM

        public GridModel GetATypeAssetAndReconAssetGLWithFixedAssetMaster(GridParameter parameters, string companyId, string fixedAssetMasterId)
        {
            try
            {
                parameters.CmdText = @"SELECT BM.Id AS BudgetMasterId, GLGI.Id AS GLGeneralInfoId, GLGI.UserName AS GLGeneralInfoName, GLGI.AccountCode AS GLGeneralInfoCode, BG.UserName AS BudgetGroup, BC.UserName AS BudgetCategory
                                        , BSC.UserName AS BudgetSubCategory, BCL.UserName AS BudgetClass, B.Id AS BudgetId, B.Code AS BudgetCode, B.UserName AS BudgetName, BM.RefNo
                                        FROM HKP.GLGeneralInfo AS GLGI
                                        LEFT OUTER JOIN HKP.GLAccountType AS GLAT ON GLAT.GLGeneralInfoId = GLGI.Id
                                        LEFT OUTER JOIN HKP.GLCompanyInfo AS GLCI ON GLCI.GLGeneralInfoId = GLGI.Id
                                        LEFT OUTER JOIN HKP.AccountGroup AS AG ON AG.Id = GLGI.AccountGroupId
                                        LEFT JOIN HKP.AccountType AS ACT ON ACT.Id =AG.AccountTypeId
                                        INNER JOIN MST.BudgetMaster AS BM ON BM.GLGeneralInfoId=GLGI.Id
                                        LEFT JOIN HKP.FixedAssetMasterBudgetTag FB ON BM.Id=FB.BudgetMasterId
                                        LEFT OUTER JOIN HKP.BudgetGroup AS BG ON BG.Id=BM.BudgetGroupId
                                        LEFT OUTER JOIN HKP.BudgetCategory AS BC ON BC.Id=BM.BudgetCategoryId
                                        LEFT OUTER JOIN HKP.BudgetSubCategory AS BSC ON BSC.Id=BM.BudgetSubCategoryId
                                        LEFT OUTER JOIN HKP.BudgetClass AS BCL ON BCL.Id=BM.BudgetClassId
                                        INNER JOIN HKP.Budget AS B ON B.Id=BM.BudgetId
                                        WHERE ACT.Id='Asset' AND GLAT.AccountType='Asset' AND GLCI.CompanyId='" + companyId + "' AND FB.FixedAssetMasterId='" + fixedAssetMasterId + "'";
                return _sqlRepository.GetGridData(parameters);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Accounts.ToString()));
            }
        }

