        public IEnumerable<object> GetMaterialConsumption(string fromDate, string toDate, string Type)
        {
            var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
            try
            {
                var sql = "";
                sql = @"SELECT 
		                            Isnull(MM.UserName,'') Material
		                            ,isnull(ART.StandardName,'') Article
		                            ,ISNULL(FCV.UserName, '') AS Sku1
		                            ,ISNULL(SCV.UserName, '') AS Sku2
		                            ,ISNULL(TCV.UserName, '') AS Sku3
		                            ,ISNULL(IGL.UserName,'') AS GL
		                            ,ISNULL(IA.UserName,'') Activity
		                            ,isnull(B.UserName,'') AS Budget
		                            --,isnull(IGL1.UserName,'') AS CGL
		                            --,isnull(IA1.UserName,'') AS CActivity
		                            --,isnull(B1.UserName,'') AS CBUdget
		                            ,Sum(IId.PolicyAmount) PolicyAmount
                            FROM trn.InventoryIssueDetail IID
                            LEFT JOIN trn.InventoryIssue II On II.Id=IId.InventoryIssueId
                            LEFT JOIN TRN.InventoryMaterial AS IM ON IM.Id = IID.InventoryMaterialId
                            LEFT JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId = MM.Id
                            LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
                            LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
                            LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
                            LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
                            LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
                            LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
                            LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
                            LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id

                            LEFT JOIN HKP.GLGeneralInfo IGL ON IGL.Id=IID.PostDrGLGeneralInfoId 
                            LEFT JOIN MST.BudgetMaster IBM ON IBM.Id=IID.PostDrBudgetMasterId
                            LEFT JOIN HKP.Activity IA ON IA.Id=IID.PostDrActivityId
                            Left JOIN hkp.Budget B On B.Id=IBM.BudgetId

                            LEFT JOIN HKP.GLGeneralInfo IGL1 ON IGL1.Id=IID.PostCrGLGeneralInfoId 
                            LEFT JOIN MST.BudgetMaster IBM1 ON IBM1.Id=IID.PostCrBudgetMasterId
                            LEFT JOIN HKP.Activity IA1 ON IA1.Id=IID.PostCrActivityId
                            Left JOIN hkp.Budget B1 On B1.Id=IBM1.BudgetId
                            where  convert(Date,II.IssueDate) between '" + fromDate + "' AND '" + toDate + @"' AND II.VoucherId IS NOT NULL
                            Group BY
                             MM.UserName
                            ,ART.StandardName
                            ,FCV.UserName
                            ,SCV.UserName
                            ,TCV.UserName
                            ,IGL.UserName
                            ,IA.UserName
                            ,B.UserName";



                return _sqlRepository.GetDataCollection(sql);

            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }
        public IEnumerable<object> GetMaterialConsumptionCostCenter(string fromDate, string toDate, string Type)
        {
            var identity = (CustomIdentity)Thread.CurrentPrincipal.Identity;
            try
            {
                var sql = "";

                sql = @"SELECT 
		                                Isnull(MM.UserName,'') Material
		                                ,isnull(ART.StandardName,'') Article
		                                ,ISNULL(FCV.UserName, '') AS Sku1
		                                ,ISNULL(SCV.UserName, '') AS Sku2
		                                ,ISNULL(TCV.UserName, '') AS Sku3
		                                ,ISNULL(IGL.UserName,'') AS GL
		                                ,ISNULL(IA.UserName,'') Activity
		                                ,isnull(B.UserName,'') AS Budget
		                                ,CC.UserName CostCenterName
		                                --,isnull(IGL1.UserName,'') AS CGL
		                                --,isnull(IA1.UserName,'') AS CActivity
		                                --,isnull(B1.UserName,'') AS CBUdget
		                                ,Sum(IId.PolicyAmount) PolicyAmount
                                FROM trn.InventoryIssueDetail IID
                                LEFT JOIN trn.InventoryIssue II On II.Id=IId.InventoryIssueId
                                LEFT JOIN ORG.CostCenter CC ON CC.Id=IID.CostCenterId
                                LEFT JOIN TRN.InventoryMaterial AS IM ON IM.Id = IID.InventoryMaterialId
                                LEFT JOIN MST.MaterialMaster AS MM ON IM.MaterialMasterId = MM.Id
                                LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
                                LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
                                LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
                                LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
                                LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
                                LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
                                LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
                                LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id

                                LEFT JOIN HKP.GLGeneralInfo IGL ON IGL.Id=IID.PostDrGLGeneralInfoId 
                                LEFT JOIN MST.BudgetMaster IBM ON IBM.Id=IID.PostDrBudgetMasterId
                                LEFT JOIN HKP.Activity IA ON IA.Id=IID.PostDrActivityId
                                Left JOIN hkp.Budget B On B.Id=IBM.BudgetId

                                LEFT JOIN HKP.GLGeneralInfo IGL1 ON IGL1.Id=IID.PostCrGLGeneralInfoId 
                                LEFT JOIN MST.BudgetMaster IBM1 ON IBM1.Id=IID.PostCrBudgetMasterId
                                LEFT JOIN HKP.Activity IA1 ON IA1.Id=IID.PostCrActivityId
                                Left JOIN hkp.Budget B1 On B1.Id=IBM1.BudgetId

                                where  convert(Date,II.IssueDate) between '" + fromDate + "' AND '" + toDate + @"' ANd IID.CostCenterId='7' AND II.VoucherId IS NOT NULL
                                Group BY
                                 MM.UserName
                                ,ART.StandardName
                                ,FCV.UserName
                                ,SCV.UserName
                                ,TCV.UserName
                                ,IGL.UserName
                                ,IA.UserName
                                ,B.UserName
                                ,CC.UserName @'";




                return _sqlRepository.GetDataCollection(sql);

            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Employees.ToString()));
            }
        }


        public IWorkbook CreateMaterialConsumptionReport(string companyId, string plantId, string fromDate, string toDate, string Qty, string Amount, string RcptIssue)
        {
            try
            {
                var excelEngine = new ExcelEngine();
                var report = new Helpers.ReportUtility();
                var workbook = report.GetWorkbook(ref excelEngine, 2);
                var sheet1 = workbook.Worksheets[0];
                var sheet2 = workbook.Worksheets[1];
                var Head = "";
                if (fromDate != "" && toDate != "")
                {
                    if (RcptIssue == "null")
                    {
                        Head = "GL Wise Material Consumption for the period";// + " " + fromDate + " " + "To" + " " + toDate;
                    }
                    else
                    {
                        Head = "Cost Center Wise Material Consumption for the period";//+ " " + fromDate + " " + "To" + " " + toDate;
                    }

                }


                CreateMaterialConsumptionReport(ref sheet1, ref sheet2, report, Head, "Summary", companyId, plantId, fromDate, toDate, Qty, Amount, RcptIssue);
                workbook.Version = ExcelVersion.Excel2016;
                return workbook;
            }
            catch (Exception)
            {
                throw;
            }
        }



        private void CreateMaterialConsumptionReport(ref IWorksheet sheet1, ref IWorksheet sheet2, ReportUtility report, string sheet1Name, string sheet2Name, string companyId, string plantId, string fromDate, string toDate, string Qty, string Amount, string RcptIssue)
        {
            var cmdText = "";
            if (fromDate != "" && toDate != "")
            {
                if (RcptIssue == "null")
                {
                    cmdText = @"SELECT  ROW_NUMBER() Over (Order by IID.Id) As [S.N],
		                        Isnull(MM.UserName,'') Material
		                        ,isnull(ART.StandardName,'') Article
		                        ,ISNULL(FCV.UserName, '') AS Sku1
		                        ,ISNULL(SCV.UserName, '') AS Sku2
		                        ,ISNULL(TCV.UserName, '') AS Sku3
		                        ,ISNULL(IGL.UserName,'') AS GL
		                        ,ISNULL(IA.UserName,'') Activity
		                        ,isnull(B.UserName,'') AS Budget
		                        --,isnull(IGL1.UserName,'') AS CGL
		                        --,isnull(IA1.UserName,'') AS CActivity
		                        --,isnull(B1.UserName,'') AS CBUdget
		                        ,Sum(IId.PolicyAmount) PolicyAmount
	                     ,MM.Id MaterialMasterID
                         ,EN.UserName EntityName
						,ART.Id MaterialMasterArticleID
                        FROM trn.InventoryIssueDetail IID
                        LEFT JOIN trn.InventoryIssue II On II.Id=IId.InventoryIssueId
                        LEFT JOIN [ORG].[Entity] EN ON EN.ID= II.EntityId
                        LEFT JOIN TRN.InventoryMaterial AS IM ON IM.Id = IID.InventoryMaterialId
                        LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
                        LEFT JOIN MST.MaterialMaster AS MM ON ART.MaterialMasterId = MM.Id
                        LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
                        LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
                        LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
                        LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
                        LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id

                        LEFT JOIN HKP.GLGeneralInfo IGL ON IGL.Id=IID.PostDrGLGeneralInfoId 
                        LEFT JOIN MST.BudgetMaster IBM ON IBM.Id=IID.PostDrBudgetMasterId
                        LEFT JOIN HKP.Activity IA ON IA.Id=IID.PostDrActivityId
                        Left JOIN hkp.Budget B On B.Id=IBM.BudgetId

                        LEFT JOIN HKP.GLGeneralInfo IGL1 ON IGL1.Id=IID.PostCrGLGeneralInfoId 
                        LEFT JOIN MST.BudgetMaster IBM1 ON IBM1.Id=IID.PostCrBudgetMasterId
                        LEFT JOIN HKP.Activity IA1 ON IA1.Id=IID.PostCrActivityId
                        Left JOIN hkp.Budget B1 On B1.Id=IBM1.BudgetId

                        where  convert(Date,II.IssueDate) between '" + fromDate + "' AND '" + toDate + @"' AND II.VoucherId IS NOT NULL
                        Group BY
                         MM.UserName
                        ,ART.StandardName
                        ,FCV.UserName
                        ,SCV.UserName
                        ,TCV.UserName
                        ,IGL.UserName
                        ,IA.UserName
                        ,B.UserName
                        ,MM.Id
                       ,ART.Id
                        ,IID.Id,EN.UserName";
                }
                else
                {
                    cmdText = @"SELECT  ROW_NUMBER() Over (Order by IID.Id) As [S.N],
		                    Isnull(MM.UserName,'') Material
		                    ,isnull(ART.StandardName,'') Article
		                    ,ISNULL(FCV.UserName, '') AS Sku1
		                    ,ISNULL(SCV.UserName, '') AS Sku2
		                    ,ISNULL(TCV.UserName, '') AS Sku3
		                    ,ISNULL(IGL.UserName,'') AS GL
		                    ,ISNULL(IA.UserName,'') Activity
		                    ,isnull(B.UserName,'') AS Budget
		                    ,CC.UserName CostCenterName
		                    --,isnull(IGL1.UserName,'') AS CGL
		                    --,isnull(IA1.UserName,'') AS CActivity
		                    --,isnull(B1.UserName,'') AS CBUdget
		                    ,Sum(IId.PolicyAmount) PolicyAmount
                        ,MM.Id MaterialMasterID
						,ART.Id MaterialMasterArticleID
                        ,EN.UserName EntityName
                    FROM trn.InventoryIssueDetail IID
                    LEFT JOIN trn.InventoryIssue II On II.Id=IId.InventoryIssueId
                    LEFT JOIN [ORG].[Entity] EN ON EN.ID= II.EntityId
                    LEFT JOIN ORG.CostCenter CC ON CC.Id=IID.CostCenterId
                    LEFT JOIN TRN.InventoryMaterial AS IM ON IM.Id = IID.InventoryMaterialId
                    LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
                    LEFT JOIN MST.MaterialMaster AS MM ON v.MaterialMasterId = MM.Id
                    LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
                    LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
                    LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
                    LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
                    LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
                    LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
                    LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
                    LEFT JOIN HKP.GLGeneralInfo IGL ON IGL.Id=IID.PostDrGLGeneralInfoId 
                    LEFT JOIN MST.BudgetMaster IBM ON IBM.Id=IID.PostDrBudgetMasterId
                    LEFT JOIN HKP.Activity IA ON IA.Id=IID.PostDrActivityId
                    Left JOIN hkp.Budget B On B.Id=IBM.BudgetId
                    LEFT JOIN HKP.GLGeneralInfo IGL1 ON IGL1.Id=IID.PostCrGLGeneralInfoId 
                    LEFT JOIN MST.BudgetMaster IBM1 ON IBM1.Id=IID.PostCrBudgetMasterId
                    LEFT JOIN HKP.Activity IA1 ON IA1.Id=IID.PostCrActivityId
                    Left JOIN hkp.Budget B1 On B1.Id=IBM1.BudgetId
                    where  convert(Date,II.IssueDate) between '" + fromDate + "' AND '" + toDate + @"'  ANd IID.CostCenterId='" + RcptIssue + @"'  AND II.VoucherId IS NOT NULL
                    Group BY
                     MM.UserName
                    ,ART.StandardName
                    ,FCV.UserName
                    ,SCV.UserName
                    ,TCV.UserName
                    ,IGL.UserName
                    ,IA.UserName
                    ,B.UserName
                    ,CC.UserName
                    ,MM.Id
                    ,ART.Id
                    ,IID.Id,EN.UserName";

                }
            }

