        #region Material Receipts Reporsts

        public IWorkbook CreateMaterialReceiptsReports(string companyId, string plantId, string fromDate, string toDate, string Qty, string Amount, string RcptIssue, string Asset, string Inventory)
        {
            try
            {
                var Head = "";
                var Head2 = "";
                var excelEngine = new ExcelEngine();
                var report = new Helpers.ReportUtility();
                var workbook = report.GetWorkbook(ref excelEngine, 2);
                var sheet1 = workbook.Worksheets[0];
                var sheet2 = workbook.Worksheets[1];

                if (Asset == "true" && Inventory == "false")
                {

                    Head = "Material receipts (Fixed Asset)";
                }


                else if (Asset == "false" && Inventory == "true")
                {

                    Head = "Material receipts (Inventory)";

                }

                else if (Asset == "true" && Inventory == "true")
                {
                    Head = "Material receipts (Fixed Asset And Inventory)";

                }



                CreateMaterialReceiptsReports(ref sheet1, ref sheet2, report, Head, "Summary", companyId, plantId, fromDate, toDate, Qty, Amount, RcptIssue, Asset, Inventory);
                workbook.Version = ExcelVersion.Excel2016;
                return workbook;
            }
            catch (Exception)
            {
                throw;
            }
        }

        private void CreateMaterialReceiptsReports(ref IWorksheet sheet1, ref IWorksheet sheet2, ReportUtility report, string sheet1Name, string sheet2Name, string companyId, string plantId, string fromDate, string toDate, string Qty, string Amount, string RcptIssue, string Asset, string Inventory)
        {
            var cmdText = "";

            if (fromDate != "" && toDate != "")
            {
                if (Asset == "true" && Inventory == "true")
                {
                    cmdText = @"SELECT  ROW_NUMBER() Over (Order by IM.Id) As [S.N],
                          MM.UserName MaterialMasterName	
						,HSNC.Code HSNCode
						, ART.StandardName ArticleName                       			
						, ISNULL(FCV.UserName,'') AS FirstCharacteristicsValue						
						, ISNULL(SCV.UserName,'') AS SecondCharacteristicsValue						
						, ISNULL(TCV.UserName,'') AS ThirdCharacteristicsValue 
						,TUoM.UserName AS UOM,IRD.IsAsset
						,Sum(IRD.TransactionQty) TransactionQty
						,Sum(ROUND(Isnull(IRD.MaterialTranAmount,0),2)) MaterialTranAmount
						,MM.Id MaterialMasterID
						,ART.Id MaterialMasterArticleID
					from TRN.InventoryMaterial AS IM
			LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
			left JOIN MST.MaterialMaster AS MM ON ART.MaterialMasterId=MM.Id
			LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
			LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
			LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
			LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
			LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
			LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
			LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
			LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
			left jOIN [TRN].[InventoryReceiveDetail] AS IRD ON IRD.InventoryMaterialId=IM.Id --and ird.InventoryReceiveId='1987'
			left jOIN [TRN].[InventoryReceive] AS IR ON IR.Id=IRD.InventoryReceiveId
			--left JOIN [TRN].[PurchaseOrderDetail] AS PID on PID.Id=IRD.PODetailsId 
			left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON IRD.BaseUOMId=TUoM.Id		
			LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id	
            where IR.PlantId='" + plantId + "' AND convert(Date,IR.GRNDate) <= '" + toDate + @"'  AND MM.UserName is not null
             Group BY
			     MM.UserName	
                 ,IRD.IsAsset
				, ART.StandardName             			
				, FCV.UserName			
				, SCV.UserName				
				, TCV.UserName
				,TUoM.UserName 
                ,MM.Id
                ,ART.Id
