        #region Material Issue Reporsts

        public IWorkbook CreateMaterialIssueReports(string companyId, string plantId, string fromDate, string toDate, string Qty, string Amount, string RcptIssue)
        {
            try
            {
                var excelEngine = new ExcelEngine();
                var report = new Helpers.ReportUtility();
                var workbook = report.GetWorkbook(ref excelEngine, 2);
                var sheet1 = workbook.Worksheets[0];
                var sheet2 = workbook.Worksheets[1];
                var Head = "";
                if (fromDate != "" && toDate != "")
                {
                    //Head = "Material issue for the period" + " " + fromDate + " " + "To" + " " + toDate;
                    Head = "Material issue for the period";

                }
                else
                {
                    Head = "Material issue as on";

                }
                CreateMaterialIssueReports(ref sheet1, ref sheet2, report, Head, "Summary", companyId, plantId, fromDate, toDate, Qty, Amount, RcptIssue);
                workbook.Version = ExcelVersion.Excel2016;
                return workbook;
            }
            catch (Exception)
            {
                throw;
            }
        }

        private void CreateMaterialIssueReports(ref IWorksheet sheet1, ref IWorksheet sheet2, ReportUtility report, string sheet1Name, string sheet2Name, string companyId, string plantId, string fromDate, string toDate, string Qty, string Amount, string RcptIssue)
        {
            var cmdText = "";

            if (fromDate != "" && toDate != "")
            {
                cmdText = @"SELECT ROW_NUMBER() Over(Order by IM.Id) As[S.N],
							MM.UserName MaterialMasterName	 
							,HSNC.Code HSNCode
							,ART.StandardName ArticleName	                       
							,ISNULL(FCV.UserName, '') AS FirstCharacteristicsValue	                      
							,ISNULL(SCV.UserName, '') AS SecondCharacteristicsValue	                        
							,ISNULL(TCV.UserName, '') AS ThirdCharacteristicsValue
							,TUoM.UserName AS UOM	 
							,Sum(Round(IID.TransactionQty,2)) TransactionQty
							,Sum(Round(IID.PolicyAmount,2)) PolicyAmount
	                       	,MM.Id MaterialMasterID
						,ART.Id MaterialMasterArticleID 
	                    ,CostC.UserName CostCenterName
						FROM trn.InventoryIssue II
						LEFT JOIN trn.InventoryIssueDetail IID ON II.Id = IId.InventoryIssueId
                        LEFT JOIN [ORG].[CostCenter] CostC ON CostC.ID=IID.CostCenterId
						LEFT JOIN ORG.Entity En ON II.EntityId = En.Id
						LEFT JOIN HKP.MaterialStorage MS ON II.MaterialStorageId = MS.Id
						LEFT JOIN TRN.InventoryMaterial AS IM ON IM.Id = IID.InventoryMaterialId
						LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
						LEFT JOIN MST.MaterialMaster AS MM ON ART.MaterialMasterId = MM.Id
						LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
						LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
						LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
						LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
						LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
						LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
						LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
						LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
						LEFT JOIN [HKP].[MaterialType] AS MT ON MGM.MaterialTypeId = MT.Id
						LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON IID.BaseUOMId = TUoM.Id

                    where  II.PlantId='" + plantId + "' AND convert(Date,II.IssueDate) BETWEEN  '" + fromDate + @"' AND '" + toDate + "' " +
                    "GROUP BY MM.UserName,ART.StandardName,FCV.UserName,SCV.UserName,TCV.UserName,TUoM.UserName ,HSNC.Code  ,MM.Id,ART.Id,IM.Id,CostC.UserName";
            }
            else
            {
                cmdText = @"SELECT ROW_NUMBER() Over(Order by IM.Id) As[S.N],
							MM.UserName MaterialMasterName	   
							,HSNC.Code HSNCode
							,ART.StandardName ArticleName	                       
							,ISNULL(FCV.UserName, '') AS FirstCharacteristicsValue	                      
							,ISNULL(SCV.UserName, '') AS SecondCharacteristicsValue	                        
							,ISNULL(TCV.UserName, '') AS ThirdCharacteristicsValue
							,TUoM.UserName AS UOM	 
							,Sum(Round(IID.TransactionQty,2)) TransactionQty
							,Sum(Round(IID.PolicyAmount,2)) PolicyAmount
	                          	,MM.Id MaterialMasterID
						,ART.Id MaterialMasterArticleID  
	                    ,CostC.UserName CostCenterName
						FROM trn.InventoryIssue II
						LEFT JOIN trn.InventoryIssueDetail IID ON II.Id = IId.InventoryIssueId
                        LEFT JOIN [ORG].[CostCenter] CostC ON CostC.ID=IID.CostCenterId
						LEFT JOIN ORG.Entity En ON II.EntityId = En.Id
						LEFT JOIN HKP.MaterialStorage MS ON II.MaterialStorageId = MS.Id
						LEFT JOIN TRN.InventoryMaterial AS IM ON IM.Id = IID.InventoryMaterialId
						LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId = ART.Id
						LEFT JOIN MST.MaterialMaster AS MM ON ART.MaterialMasterId = MM.Id
						LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
						LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId = MGM.Id
						LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId = FC.Id
						LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId = SC.Id
						LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId = TC.Id
						LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId = FCV.Id
						LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId = SCV.Id
						LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId = TCV.Id
						LEFT JOIN [HKP].[MaterialType] AS MT ON MGM.MaterialTypeId = MT.Id
						LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON IID.BaseUOMId = TUoM.Id

                    where  II.PlantId='" + plantId + "' AND convert(Date,II.IssueDate) <= '" + toDate + "'	" +
                    "GROUP BY MM.UserName,ART.StandardName,FCV.UserName,SCV.UserName,TCV.UserName,TUoM.UserName ,HSNC.Code  ,MM.Id,ART.Id,IM.Id,CostC.UserName";
            }

            var inventoryMaterialList = _sqlRepository.GetDataTable(cmdText);
            var plantName = new DataView(_sqlRepository.GetDataTable(@"SELECT UserName from org.Plant WHERE Id='" + plantId + "'")).ToTable(true, "UserName").Rows[0]["UserName"].ToString();


