        public IWorkbook MaterialMasterStatus(string companyId, string plantId, string fromDate, string toDate, string Qty, string Amount, string RcptIssue, string Asset, string Inventory)
        {
            try
            {
                var excelEngine = new ExcelEngine();
                var report = new Helpers.ReportUtility();
                var workbook = report.GetWorkbook(ref excelEngine, 2);
                var sheet1 = workbook.Worksheets[0];
                var sheet2 = workbook.Worksheets[1];
                var Head = "";
                if (Asset == "true" && Inventory == "false")
                {

                    Head = "Material Master (With Stock)";
                }

                else if (Asset == "false" && Inventory == "true")
                {

                    Head = "Material Master (Without Stock)";


                }


                else if (Asset == "true" && Inventory == "true")
                {
                    Head = "Material Master (With Stock and Without Stock)";

                }

                CreateMaterialMasterStatusSheet(ref sheet1, ref sheet2, report, Head, "Summary", companyId, plantId, fromDate, toDate, Qty, Amount, RcptIssue, Asset, Inventory);
                workbook.Version = ExcelVersion.Excel2016;
                return workbook;
            }
            catch (Exception)
            {
                throw;
            }
        }



        private void CreateMaterialMasterStatusSheet(ref IWorksheet sheet1, ref IWorksheet sheet2, ReportUtility report, string sheet1Name, string sheet2Name, string companyId, string plantId, string fromDate, string toDate, string Qty, string Amount, string RcptIssue, string Asset, string Inventory)
        {

            var cmdText = "";
            if (Asset == "true" && Inventory == "true")
            {

                cmdText = @"SELECT ROW_NUMBER() Over(Order by  MM.Id) As[S.N],   
									MT.Id MaterialTypeId,IRD.StorageName,HSNC.Code HSNCode
                                    ,isnull(MT.UserName,'') MaterialType
                                    ,isnull(MGM.Id,'') AS MaterialGroupMasterId		
                                    ,isnull(MGM.UserName,'') AS MaterialGroupMasterName		
                                    ,MM.Id MaterialMasterId
                                    ,MM.Code MaterialCode
                                    ,isnull(MM.UserName,'') MaterialMasterName	
                                    ,AttributeNames=STUFF((select ','+xPDAMAP.StandardName from
						                                    [MST].[MaterialMasterArticleValue] AS Xart
						                                    left outer JOin [HKP].MaterialAttribute xPDAMAP on xPDAMAP.Id=Xart.MaterialAttributeId					
						                                    where Xart.MaterialMasterArticleId=ART.Id group by xPDAMAP.StandardName,xPDAMAP.Sequence order by xPDAMAP.Sequence  for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '')

                               ,AttributeValues=STUFF((select ','+isnull(xPDAMAP.Username,Xart1.MaterialAttributeValueFreeText) from

						                                    [MST].[MaterialMasterArticleValue] AS Xart1
						                                    left outer JOin [HKP].[MaterialAttributeValue] xPDAMAP on xPDAMAP.Id=Xart1.MaterialAttributeValueId	
															left outer join hkp.MaterialAttribute xATT on xATT.id=xPDAMAP.MaterialAttributeId
						                                    where Xart1.MaterialMasterArticleId=ART.Id group by xPDAMAP.Username,Xart1.MaterialAttributeValueFreeText,xATT.Sequence order by xATT.Sequence for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '') 
			
                                    ,ART.Id ArticleId
                                    ,isnull( ART.StandardName,'') ArticleName	
                                    , ISNULL(FCV.UserName,'') AS FirstCharacteristicsValue
                                    , ISNULL(SCV.UserName,'') AS SecondCharacteristicsValue
                                    , ISNULL(TCV.UserName,'') AS ThirdCharacteristicsValue 	
                                    ,TUoM.UserName UOM
                                    --,GRNIsAsset= CASE WHEN IRD.IsAsset=0 THEN 'Inventory' ELSE 'Asset' END
                                    ,IsAsset= CASE WHEN MM.IsAsset=0 THEN 'Inventory' ELSE 'Asset' END

                                    --,isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0) As OpeningBalance	
                                    --,isnull(opbal.TotalMaterialBooksCurrencyAmount,0) AS OpeningBalanceAmount						

                                    --,isnull(opbal2.TransactionQty,0) ReceivedForThePeriod
                                    --,isnull(opbal2.TotalMaterialBooksCurrencyAmount,0) AS ReceivedForThePeriodAmount

                         
                                    --,isnull(IFD1.IssueQty,0) IssueForThePeriod	
                                    --,isnull(IFD1.PolicyAmount,0) IssueForThePeriodAmount	

                                    --,(isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0) + isnull(opbal2.TransactionQty,0))-isnull(IFD1.IssueQty,0) Closing
                                    --,(isnull(opbal.TotalMaterialBooksCurrencyAmount,0) + isnull(opbal2.TotalMaterialBooksCurrencyAmount,0))-isnull(IFD1.PolicyAmount,0) ClosingAmount
                                    


                         	--Opening Balance
                           ,isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0) As OpeningBalance	
							,isnull(opbal.TotalMaterialBooksCurrencyAmount,0)-isnull(IFD3.PolicyAmount,0) AS OpeningBalanceAmount

						    --Receive

							,isnull(opbal2.TransactionQty,0) ReceivedForThePeriod
							,isnull(opbal2.TotalMaterialBooksCurrencyAmount,0) AS ReceivedForThePeriodAmount
							--Issue
                         
							,isnull(IFD1.IssueQty,0) IssueForThePeriod	
							,isnull(IFD1.PolicyAmount,0) IssueForThePeriodAmount	

							--Issue Return
							,isnull(IssueReturnData.Qty,0) IssueReturnQtyForThePeriod	
							,isnull(IssueReturnData.IssueReturnAmount,0) IssueReturnForThePeriodAmount	

							--Purchase Return
							,isnull(PurchaseReturnData.Qty,0) PurchaseReturnQtyForThePeriod	
							,isnull(PurchaseReturnData.PurchaseReturnAmount,0) PurchaseReturnForThePeriodAmount	

							--Adjust Return
							,isnull(AdjustmentData.Qty,0) AdjustmentQtyForThePeriod	
							,isnull(AdjustmentData.AdjustmentAmount,0) AdjustmentForThePeriodAmount	

							--Balance
							--,(isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0) + isnull(opbal2.TransactionQty,0))-isnull(IFD1.IssueQty,0) Closing
							--,(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)-isnull(IFD3.PolicyAmount,0) + isnull(opbal2.TotalMaterialBooksCurrencyAmount,0))-isnull(IFD1.PolicyAmount,0) ClosingAmount
							,((((isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0) + isnull(opbal2.TransactionQty,0))-isnull(IFD1.IssueQty,0)-isnull(PurchaseReturnData.Qty,0))-isnull(AdjustmentData.Qty,0))+isnull(IssueReturnData.Qty,0)) Closing
							,((((isnull(opbal.TotalMaterialBooksCurrencyAmount,0)-isnull(IFD3.PolicyAmount,0) + isnull(opbal2.TotalMaterialBooksCurrencyAmount,0))-isnull(IFD1.PolicyAmount,0)-isnull(AdjustmentData.AdjustmentAmount,0))-isnull(PurchaseReturnData.PurchaseReturnAmount,0))+isnull(IssueReturnData.IssueReturnAmount,0)) ClosingAmount

                        ,'' Remarks
                        FROM MST.MaterialMaster AS MM
						LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
                        LEFT JOIN (select * from  TRN.InventoryMaterial where  PlantId='" + plantId + @"') AS IM ON IM.MaterialMasterId=MM.Id
                        LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
                        LEFT JOIN MST.MaterialMasterArticle AS ART ON IM.ArticleId=ART.Id
                        LEFT JOIN HKP.Characteristics AS FC ON IM.FirstCharacteristicsId=FC.Id
                        LEFT JOIN HKP.Characteristics AS SC ON IM.SecondCharacteristicsId=SC.Id
                        LEFT JOIN HKP.Characteristics AS TC ON IM.ThirdCharacteristicsId=TC.Id
                        LEFT JOIN HKP.CharacteristicsValue AS FCV ON IM.FirstCharacteristicsValueId=FCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS SCV ON IM.SecondCharacteristicsValueId=SCV.Id
                        LEFT JOIN HKP.CharacteristicsValue AS TCV ON IM.ThirdCharacteristicsValueId=TCV.Id
                            LEFT jOIN (select IRD.InventoryMaterialId,IRD.TransactionUoMId,IR.CurrencyId,GRNDate,IRD.MaterialStorageId,IR.PlantId,MS.UserName StorageName from [TRN].[InventoryReceiveDetail] IRD 
										left JOIN [TRN].[InventoryReceive] AS IR ON IRD.InventoryReceiveId=IR.Id
                                        LEFT JOIN [HKP].[MaterialStorage] AS MS ON MS.ID=IRD.MaterialStorageId
										GROUP BY InventoryMaterialId,IRD.TransactionUoMId,IR.CurrencyId,GRNDate,IR.PlantId ,IRD.MaterialStorageId,MS.UserName
									 ) AS IRD ON IRD.InventoryMaterialId=IM.Id
                        left JOIN [SCS].[UnitOfMeasurement] AS TUoM ON IRD.TransactionUoMId=TUoM.Id
                        left JOIN [SCS].[Currency] AS CU ON IRD.CurrencyId=CU.Id
                        LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
                        LEFT join(  SELECT IRD.InventoryMaterialId, Sum(IRD.TransactionQty) AS TransactionQty,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
			                        FROM  [TRN].[InventoryReceiveDetail] IRD
			                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
			                        where convert(Date,IR.GRNDate) <= '" + fromDate + @"' AND IR.OpeningBalanceId IS NOT NULL group By IRD.InventoryMaterialId--) AS opbal ON opbal.InventoryMaterialId=IM.Id AND IM.PlantId='20171'
                                    UNION ALL
                                    SELECT IRD.InventoryMaterialId, Sum(IRD.TransactionQty) AS TransactionQty,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
			                        FROM  [TRN].[InventoryReceiveDetail] IRD
			                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
			                        where convert(Date,IR.GRNDate) < '" + fromDate + @"' AND IR.OpeningBalanceId IS NULL  group By IRD.InventoryMaterialId) AS opbal ON opbal.InventoryMaterialId=IM.Id AND IM.PlantId='" + plantId + @"'

                        LEFT join(  SELECT IRD.InventoryMaterialId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
			                        FROM  [TRN].[InventoryReceiveDetail] IRD
			                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
			                        where convert(Date,IR.GRNDate) > '" + toDate + @"'  group By IRD.InventoryMaterialId--) AS opbal1 ON opbal1.InventoryMaterialId=IM.Id AND IM.PlantId='" + plantId + @"'
                                    UNION ALL
                                    SELECT IRD.InventoryMaterialId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
			                        FROM  [TRN].[InventoryReceiveDetail] IRD
			                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
			                        where convert(Date,IR.GRNDate) = '" + toDate + @"'  group By IRD.InventoryMaterialId) AS opbal1 ON opbal1.InventoryMaterialId=IM.Id AND IM.PlantId='" + plantId + @"'

                        LEFT join(SELECT IRD.InventoryMaterialId, Sum(IRD.TransactionQty) AS TransactionQty ,  Sum(IRD.TotalMaterialBooksCurrencyAmount) TotalMaterialBooksCurrencyAmount
			                        FROM  [TRN].[InventoryReceiveDetail] IRD
			                        LEFT JOIN [TRN].[InventoryReceive] IR ON IR.Id=IRD.InventoryReceiveId
			                        where convert(Date,IR.GRNDate)
                                    BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' AND IR.OpeningBalanceId IS  NULL group By IRD.InventoryMaterialId) AS opbal2 ON opbal2.InventoryMaterialId=IM.Id AND IM.PlantId='" + plantId + @"'

                        LEFT join (select IID.InventoryMaterialId, Sum(IID.TransactionQty) OpeningIssueQty, Sum(IID.PolicyAmount) PolicyAmount
			                        FROM TRN.InventoryIssueDetail IID  
			                        LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 									
			                        WHERE convert(Date,II.IssueDate) < '" + fromDate + "' AND II.PlantId='" + plantId + @"' GROUP BY IID.InventoryMaterialId
			                        ) IFD3 On IFD3.InventoryMaterialId=IM.Id
                        LEFT join (select IID.InventoryMaterialId, Sum(IID.TransactionQty) IssueQty , Sum(IID.PolicyAmount) PolicyAmount
			                        FROM TRN.InventoryIssueDetail IID  
			                        LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 
			                        --LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId=IID.Id
			                        WHERE convert(Date,II.IssueDate) = '" + toDate + @"' AND II.PlantId='" + plantId + @"'  GROUP BY IID.InventoryMaterialId
			                        ) IFD On IFD.InventoryMaterialId=IM.Id

                        LEFT join (select IID.InventoryMaterialId, Sum(IID.TransactionQty) IssueQty , Sum(IID.PolicyAmount) PolicyAmount
			                        FROM TRN.InventoryIssueDetail IID  
			                        LEFT JOIN TRN.InventoryIssue II ON IID.InventoryIssueId=II.Id	 
			                        --LEFT JOIN TRN.InventoryIssueHistory IH On IH.InventoryIssueDetailId=IID.Id
		                        WHERE convert(Date,II.IssueDate) BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' AND II.PlantId='" + plantId + @"' GROUP BY IID.InventoryMaterialId
		                        ) IFD1 On IFD1.InventoryMaterialId=IM.Id

                        --Issue Return
                        Left join (select IH.InventoryMaterialId,sum(IH.Qty) Qty,sum(IRD.MaterialTranRate) MaterialTranRate, (sum(IH.Qty)*sum(IRD.MaterialTranRate)) IssueReturnAmount from trn.InventoryIssueReturnHistory IH
									 Left join trn.InventoryIssueReturn II ON II.Id=IH.InventoryIssueReturnId
									 Left join trn.InventoryReceiveDetail IRD ON IRD.Id=IH.InventoryReceiveDetailId
									 	WHERE convert(Date,II.IssueDate) BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' AND II.PlantId='" + plantId + @"' GROUP BY IH.InventoryMaterialId
								 )IssueReturnData ON IssueReturnData.InventoryMaterialId=IM.Id
					    --Purchase return
                       Left join (select IH.InventoryMaterialId,sum(IH.TransactionQty) Qty,sum(IRD.MaterialTranRate) MaterialTranRate, (sum(IH.TransactionQty)*sum(IRD.MaterialTranRate)) PurchaseReturnAmount 
					                 from trn.PurchaseReturnDetail IH
									 Left join trn.PurchaseReturn II ON II.Id=IH.PurchaseReturnId
									 Left join trn.InventoryReceiveDetail IRD ON IRD.Id=IH.InventoryReceiveDetailId
									 	WHERE convert(Date,II.[POReturnDate]) BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' AND II.PlantId='" + plantId + @"' GROUP BY IH.InventoryMaterialId
								 )PurchaseReturnData ON PurchaseReturnData.InventoryMaterialId=IM.Id

                       -- Adjustment
						Left join (select psad.InventoryMaterialId,sum(IH.Qty) Qty,sum(IH.Rate) Rate, (sum(IH.Qty)*sum(IH.Rate)) AdjustmentAmount 
					                 from trn.PhysicalStockAdjustmentHistory IH
									 Left JOIN TRN.PhysicalStockAdjustmentDetail psad on psad.Id=IH.PhysicalStockAdjustmentDetailId
									 Left join trn.PhysicalStockAdjustmentMaster II ON II.Id=psad.PhysicalStockAdjustmentMasterID
									 --Left join trn.InventoryReceiveDetail IRD ON IRD.Id=IH.InventoryReceiveDetailId
									 WHERE convert(Date,II.IssueDate) BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' AND II.PlantId='" + plantId + @"' GROUP BY psad.InventoryMaterialId
								 )AdjustmentData ON AdjustmentData.InventoryMaterialId=IM.Id 

                --where IRD.InventoryMaterialId <>''
where IRD.InventoryMaterialId <>'' and convert(Date,IRD.GRNDate) BETWEEN  '" + fromDate + @"' AND '" + toDate + @"' AND IRD.PlantId='" + plantId + @"'

             
                        UNION ALL

		                SELECT ROW_NUMBER() Over(Order by  MM.Id) As[S.N],   
                        MT.Id MaterialTypeId,'' StorageName
						,HSNC.Code HSNCode
                            ,isnull(MT.UserName,'') MaterialType
                            ,isnull(MGM.Id,'') AS MaterialGroupMasterId		
                            ,isnull(MGM.UserName,'') AS MaterialGroupMasterName		
	                            ,MM.Id MaterialMasterId
                                ,MM.Code MaterialCode
	                            ,isnull(MM.UserName,'') MaterialMasterName	
	                            ,AttributeNames=STUFF((select ','+xPDAMAP.StandardName from
						                                    [MST].[MaterialMasterArticleValue] AS Xart
						                                    left outer JOin [HKP].MaterialAttribute xPDAMAP on xPDAMAP.Id=Xart.MaterialAttributeId					
						                                    where Xart.MaterialMasterArticleId=ART.Id group by xPDAMAP.StandardName,xPDAMAP.Sequence order by xPDAMAP.Sequence  for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '')

                               ,AttributeValues=STUFF((select ','+isnull(xPDAMAP.Username,Xart1.MaterialAttributeValueFreeText) from

						                                    [MST].[MaterialMasterArticleValue] AS Xart1
						                                    left outer JOin [HKP].[MaterialAttributeValue] xPDAMAP on xPDAMAP.Id=Xart1.MaterialAttributeValueId	
															left outer join hkp.MaterialAttribute xATT on xATT.id=xPDAMAP.MaterialAttributeId
						                                    where Xart1.MaterialMasterArticleId=ART.Id group by xPDAMAP.Username,Xart1.MaterialAttributeValueFreeText,xATT.Sequence order by xATT.Sequence for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '') 

                            ,ART.Id ArticleId
	                            ,isnull( ART.StandardName,'') ArticleName	
	                       
	                            , '' AS FirstCharacteristicsValue
	                            , '' AS SecondCharacteristicsValue
	                            , '' AS ThirdCharacteristicsValue
	                            ,TUoM.UserName UOM
	                            --,GRNIsAsset= CASE WHEN IRD.IsAsset=0 THEN 'Inventory' ELSE 'Asset' END
	                            ,IsAsset= CASE WHEN MM.IsAsset=0 THEN 'Inventory' ELSE 'Asset' END
	                            --,0 As OpeningBalance	
	                            --,0 AS OpeningBalanceAmount				

	                            --,0 ReceivedForThePeriod
	                            --,0 AS ReceivedForThePeriodAmount                         
	                            --,0 IssueForThePeriod	
	                            --,0 IssueForThePeriodAmount	

	                            --,0 Closing
	                            --,0 ClosingAmount
                                ,0 As OpeningBalance	
							,0 AS OpeningBalanceAmount

						    --Receive

							,0 ReceivedForThePeriod
							,0 AS ReceivedForThePeriodAmount
							--Issue
                         
							,0 IssueForThePeriod	
							,0 IssueForThePeriodAmount	

							--Issue Return
							,0 IssueReturnQtyForThePeriod	
							,0 IssueReturnForThePeriodAmount	

							--Purchase Return
							,0 PurchaseReturnQtyForThePeriod	
							,0 PurchaseReturnForThePeriodAmount	

							--Adjust Return
							,0 AdjustmentQtyForThePeriod	
							,0 AdjustmentForThePeriodAmount	

							--Balance
							--,(isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0) + isnull(opbal2.TransactionQty,0))-isnull(IFD1.IssueQty,0) Closing
							--,(isnull(opbal.TotalMaterialBooksCurrencyAmount,0)-isnull(IFD3.PolicyAmount,0) + isnull(opbal2.TotalMaterialBooksCurrencyAmount,0))-isnull(IFD1.PolicyAmount,0) ClosingAmount
							,0 Closing
							,0 ClosingAmount
	                            ,'' Remarks
                        FROM MST.MaterialMaster AS MM
						LEFT JOIN [HKP].[HSNCode] AS HSNC ON HSNC.ID=MM.HSNCodeId
                       -- LEFT JOIN (select * from  TRN.InventoryMaterial where  PlantId='" + plantId + @"') AS IM ON IM.MaterialMasterId=MM.Id
                        LEFT JOIN MST.MaterialGroupMaster AS MGM ON MM.MaterialGroupMasterId=MGM.Id
						 LEFT JOIN [HKP].[MaterialType] AS MT On MGM.MaterialTypeId=MT.Id
                        LEFT JOIN MST.MaterialMasterArticle AS ART ON ART.MaterialMasterId=mm.Id                       
                       
                        LEFT JOIN [SCS].[UnitOfMeasurement] AS TUoM ON MM.BaseUOMId=TUoM.Id	
						where MM.id not in (select MaterialMasterId from  TRN.InventoryMaterial where  MaterialMasterId IS NOT NULL AND PlantId='" + plantId + @"')";
            }
            else if (Asset == "true" && Inventory == "false")
            {

                cmdText = @"SELECT ROW_NUMBER() Over(Order by  MM.Id) As[S.N],   
                            MT.Id MaterialTypeId ,IRD.StorageName
							,HSNC.Code HSNCode
