                            ,TUoM.UserName UOM
                            --,GRNIsAsset= CASE WHEN IRD.IsAsset=0 THEN 'Inventory' ELSE 'Asset' END
                            ,IsAsset= CASE WHEN MM.IsAsset=0 THEN 'Inventory' ELSE 'Asset' END
                            --,isnull(opbal.TransactionQty,0)-isnull(IFD3.OpeningIssueQty,0) As OpeningBalance	
